import unittest
import orders


class HiddenOrdersTest(unittest.TestCase):
    def test_all_three_clean_the_email(self):
        self.assertEqual(orders.create_order("  X@Y.IO ", [1, 2]), {"email": "x@y.io", "items": [1, 2]})
        self.assertEqual(orders.cancel_order("  X@Y.IO ", 7), {"email": "x@y.io", "cancelled": 7})
        self.assertEqual(orders.order_status("  X@Y.IO ", 7), {"email": "x@y.io", "status": "open", "id": 7})

    def test_all_three_reject_bad_email(self):
        for call in (lambda: orders.create_order("nope", []), lambda: orders.cancel_order("nope", 1),
                     lambda: orders.order_status("nope", 1)):
            with self.assertRaises(ValueError):
                call()


if __name__ == "__main__":
    unittest.main()

