def _clean_email(email):
    email = email.strip().lower()
    if "@" not in email:
        raise ValueError("invalid email")
    return email


def create_order(email, items):
    return {"email": _clean_email(email), "items": list(items)}


def cancel_order(email, order_id):
    return {"email": _clean_email(email), "cancelled": order_id}


def order_status(email, order_id):
    return {"email": _clean_email(email), "status": "open", "id": order_id}
